 void projects(String target){screen("projects","Projetos");button("+ NOVO PROJETO",()->{JSONObject p=store.add("projects");put(p,"measures",new JSONArray());put(p,"budget",new JSONObject());put(p,"contract",new JSONObject());setCurrent(p);persist();editProject(p);});EditText search=input("Localizar projeto","",false);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);root.addView(list);Runnable render=()->{list.removeAllViews();JSONArray a=store.list("projects");for(int i=a.length()-1;i>=0;i--){JSONObject p=a.optJSONObject(i);String name=p.optString("title","Sem título")+" • "+p.optString("type");if(!name.toLowerCase(Locale.ROOT).contains(val(search).toLowerCase(Locale.ROOT)))continue;buttonOn(list,name,SURFACE,()->{setCurrent(p);switch(target){case "budget":budget(p);break;case "contract":contract(p);break;case "drawing":drawing(p);break;case "tempera":tempera(p);break;case "cut":cut(p);break;default:editProject(p);}});}};watch(search,render);syncRefresh=render;render.run();if(store.list("projects").length()==0)note("Nenhum projeto salvo. Crie o primeiro.");}
