 final class MeasureRow{
 EditText label,value;Spinner dimension,unit;String previous;final LinearLayout box;final String[] names={"Largura","Altura","Profundidade","Diâmetro","Outra"};
 String name(){return dimension.getSelectedItemPosition()==4?val(label):dimension.getSelectedItem().toString();}
 MeasureRow(String name,String val,String u){box=new LinearLayout(MainActivity.this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(px(12),px(10),px(12),px(10));box.setBackground(shape(SURFACE,12));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=px(12);measureBox.addView(box,lp);TextView cap=new TextView(MainActivity.this);cap.setText("DIMENSÃO");cap.setTextColor(MUTED);box.addView(cap);dimension=new Spinner(MainActivity.this);dimension.setAdapter(new ArrayAdapter<>(MainActivity.this,R.layout.glass_selector_item,names));int selected=4;for(int i=0;i<4;i++)if(names[i].equalsIgnoreCase(name))selected=i;dimension.setSelection(selected);box.addView(dimension);label=new EditText(MainActivity.this);label.setTextColor(TEXT);label.setHint("Nome da dimensão");label.setHintTextColor(MUTED);label.setText(selected==4&& !name.equals("Outra")?name:"");label.setVisibility(selected==4?View.VISIBLE:View.GONE);box.addView(label);TextView help=new TextView(MainActivity.this);help.setText("VALOR  •  UNIDADE DESTA DIMENSÃO");help.setTextColor(MUTED);box.addView(help);LinearLayout line=new LinearLayout(MainActivity.this);box.addView(line);value=new EditText(MainActivity.this);value.setTextColor(TEXT);value.setHintTextColor(MUTED);value.setHint("Ex.: 2 ou 2,50");value.setText(val);value.setSingleLine(true);value.setKeyListener(android.text.method.TextKeyListener.getInstance());value.setRawInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL|android.text.InputType.TYPE_NUMBER_FLAG_SIGNED);line.addView(value,new LinearLayout.LayoutParams(0,px(56),1));unit=new Spinner(MainActivity.this);unit.setAdapter(new ArrayAdapter<>(MainActivity.this,R.layout.glass_selector_item,new String[]{"mm","cm","m"}));previous=Arrays.asList("mm","cm","m").contains(u)?u:"mm";unit.setSelection(Arrays.asList("mm","cm","m").indexOf(previous));line.addView(unit,new LinearLayout.LayoutParams(px(120),px(56)));dimension.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,View v,int pos,long id){label.setVisibility(pos==4?View.VISIBLE:View.GONE);}});unit.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,View v,int pos,long id){String next=unit.getSelectedItem().toString();if(next.equals(previous))return;try{if(!MainActivity.this.val(value).isEmpty())value.setText(Measures.convert(MainActivity.this.val(value),previous,next));previous=next;}catch(Exception e){unit.setSelection(Arrays.asList("mm","cm","m").indexOf(previous));message(e.getMessage());}}});buttonOn(box,"Remover dimensão",0xff4c5868,()->{rows.remove(this);measureBox.removeView(box);});}
 }
 void addRow(String n,String v,String u){if(rows.size()>=24)throw new IllegalArgumentException("Até 24 dimensões por projeto.");rows.add(new MeasureRow(n,v,u));}
 void validateProject(JSONObject p)throws Exception{if(p.optString("title").trim().isEmpty()||p.optString("type").trim().isEmpty())throw new Exception("Informe nome e tipo do projeto.");JSONArray a=p.optJSONArray("measures");if(a==null||a.length()==0)throw new Exception("Informe as medidas reais.");Set<String> names=new HashSet<>();for(int i=0;i<a.length();i++){JSONObject m=a.getJSONObject(i);String n=m.optString("label").trim();if(n.isEmpty()||!names.add(n.toLowerCase(Locale.ROOT)))throw new Exception("Informe nomes únicos para cada dimensão.");m.put("mm",Measures.mm(m.optString("value"),m.optString("unit")));}}
 BigDecimal measure(JSONObject p,String name)throws Exception{JSONArray a=p.getJSONArray("measures");for(int i=0;i<a.length();i++){JSONObject m=a.getJSONObject(i);if(name.equalsIgnoreCase(m.optString("label")))return new BigDecimal(Measures.mm(m.getString("value"),m.getString("unit")));}throw new Exception("Informe a dimensão "+name+" no projeto.");}
 void drawing(JSONObject p)throws Exception{validateProject(p);double w=measure(p,"Largura").doubleValue(),h=measure(p,"Altura").doubleValue(),depth=0;try{depth=measure(p,"Profundidade").doubleValue();}catch(Exception ignored){}screen("drawing","Representação 2D / 3D");note(p.optString("title")+" • "+p.optString("type"));note("Representação geométrica determinística. Não define ferragens, perfis, espessura ou medidas de fabricação. Traços de identificação são simbólicos, sem espessura técnica. Box com retorno exige Profundidade informada.");ProjectDrawing view=new ProjectDrawing(this,w,h,depth,p.optInt("visualPanels",1));view.service=p.optString("type");if(!p.has("visualPanels")){java.util.regex.Matcher leaves=java.util.regex.Pattern.compile("(?i)([0-9]{1,2})\\s*(?:folhas|painéis|paineis)").matcher(p.optString("model")+" "+p.optString("configuration"));if(leaves.find()){int count=Integer.parseInt(leaves.group(1));if(count>=1&&count<=20)view.panels=count;}}root.addView(view,new LinearLayout.LayoutParams(-1,px(340)));button("ALTERNAR 2D / 3D",()->{view.threeD=!view.threeD;view.invalidate();});button("MOSTRAR / OCULTAR MEDIDAS",()->{view.dimensions=!view.dimensions;view.invalidate();});button("RESETAR VISÃO",view::reset);button("ZOOM +",()->view.setZoom(view.zoom*1.15f));button("ZOOM −",()->view.setZoom(view.zoom/1.15f));if(Math.min(w,h)/Math.max(w,h)<.02)note("ATENÇÃO: proporção muito estreita. Confira as unidades individuais no projeto. As dimensões físicas não foram alteradas.");if(p.optString("type").toLowerCase(Locale.ROOT).contains("box")&&depth==0)button("INFORMAR PROFUNDIDADE / CONFIGURAÇÃO",()->editProject(p));note("Arraste para girar • pinça para zoom");EditText panels=number("Divisões visuais informadas pelo profissional (1 a 20)",String.valueOf(view.panels));button("APLICAR DIVISÕES",()->{int count=Integer.parseInt(val(panels));if(count<1||count>20)throw new Exception("Informe 1 a 20 divisões.");put(p,"visualPanels",count);view.panels=count;view.invalidate();persist();});button("VOLTAR AO PROJETO",()->go(()->editProject(p)));}
 void contacts(String key,boolean select){screen("contacts",key.equals("clients")?"Clientes":"Fornecedores");note(sync!=null&&!sync.state.optString("tenant").isEmpty()?"Cadastro integrado ao PDV. Alterações são sincronizadas automaticamente; pendências e conflitos aparecem em Integração com o PDV.":"Rascunhos locais. Conecte o PDV na área de integração para compartilhar os cadastros.");button("+ CADASTRAR "+(key.equals("clients")?"CLIENTE":"FORNECEDOR"),()->contactEditor(key,null,select));EditText search=input("Localizar por nome ou documento","",false);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);root.addView(list);Runnable render=()->{list.removeAllViews();JSONArray a=store.list(key);java.util.HashSet<String> officialSeen=new java.util.HashSet<>();for(int i=0;i<a.length();i++){JSONObject c=a.optJSONObject(i);if(!c.isNull("pdvId")&&!c.optString("pdvId").isEmpty()&&!officialSeen.add(c.optString("pdvId")))continue;if(!(c.optString("name")+" "+c.optString("document")).toLowerCase(Locale.ROOT).contains(val(search).toLowerCase(Locale.ROOT)))continue;buttonOn(list,c.optString("name")+"\n"+c.optString("phone"),SURFACE,()->{if(select&&current!=null)new InteriorVisuals.Dialog(this).setTitle(c.optString("name")).setItems(new String[]{"SELECIONAR CLIENTE PARA O PROJETO","EDITAR DADOS"},(d,n)->run(()->{if(n==0){put(current,"clientLocalId",c.optString("id"));persist();editProject(current);}else contactEditor(key,c,true);})).show();else contactEditor(key,c,false);});}};watch(search,render);syncRefresh=render;render.run();if(select)note("Abra o cliente e toque em SELECIONAR CLIENTE PARA O PROJETO.");}
 void contactEditor(String key,JSONObject record,boolean select){screen("contact","Cadastro local");EditText name=input("Nome",record==null?"":record.optString("name"),false),doc=input("Documento (opcional)",record==null?"":record.optString("document"),false),phone=input("Telefone",record==null?"":record.optString("phone"),false),email=input("E-mail",record==null?"":record.optString("email"),false),address=input("Endereço",record==null?"":record.optString("address"),true);EditText cep=input("CEP",record==null?"":record.optString("cep"),false),street=input("Rua / logradouro",record==null?"":record.optString("street"),false),number=input("Número",record==null?"":record.optString("number"),false),complement=input("Complemento",record==null?"":record.optString("complement"),false),district=input("Bairro",record==null?"":record.optString("district"),false),city=input("Cidade",record==null?"":record.optString("city"),false),uf=input("UF",record==null?"":record.optString("uf"),false);TextView cepState=text("CEP opcional. Sem internet, preencha o endereço manualmente.",14,MUTED);CepLookup.bind(this,cep,street,district,city,uf,cepState);button("PREENCHER ENDEREÇO COM OS DADOS DO CEP",()->address.setText(CepLookup.compose(val(address),street,number,complement,district,city,uf,cep)));button("SALVAR CADASTRO",()->{if(val(name).isEmpty())throw new Exception("Informe o nome.");String document=val(doc).replaceAll("[^0-9A-Za-z]","");for(int i=0;i<store.list(key).length();i++){JSONObject other=store.list(key).getJSONObject(i);if(other==record)continue;if(!document.isEmpty()&&document.equalsIgnoreCase(other.optString("document").replaceAll("[^0-9A-Za-z]","")))throw new Exception("Esse documento já existe. Localize e utilize o cadastro existente.");}JSONObject c=record==null?store.add(key):record;put(c,"name",val(name));put(c,"document",val(doc));put(c,"phone",val(phone));put(c,"email",val(email));put(c,"address",val(address).equals(record==null?"":record.optString("address"))?CepLookup.compose(val(address),street,number,complement,district,city,uf,cep):val(address));put(c,"cep",val(cep));put(c,"street",val(street));put(c,"number",val(number));put(c,"complement",val(complement));put(c,"district",val(district));put(c,"city",val(city));put(c,"uf",val(uf));persist();contacts(key,select);});note("Salvar cadastro não vincula silenciosamente ao projeto. Selecione o cliente após salvar.");}
 void materials(){screen("materials","Materiais");note("Catálogo local de trabalho. Sem baixa de estoque, preços ou especificações presumidas.");button("+ MATERIAL",()->materialEditor(null));JSONArray a=store.list("materials");for(int i=0;i<a.length();i++){JSONObject m=a.optJSONObject(i);button(m.optString("name")+" • "+m.optString("specification"),()->materialEditor(m));}}
 void materialEditor(JSONObject old){screen("material","Material informado");if(old!=null&&!old.isNull("pdvId")){text(old.optString("name"),21,TEXT);note("PRODUTO DO PDV • "+old.optString("barcode")+"\nCategoria: "+old.optString("category")+"\nPreço: "+old.optString("price")+"\nEstoque informado pelo PDV: "+old.optString("stock"));note("Este cadastro é controlado no PDV. Não há entrada, saída ou alteração de preço pelo app.");button("VOLTAR AOS MATERIAIS",this::materials);return;}EditText name=input("Descrição",old==null?"":old.optString("name"),false),spec=input("Especificação informada pelo profissional",old==null?"":old.optString("specification"),true);button("SALVAR MATERIAL",()->{if(val(name).isEmpty())throw new Exception("Informe a descrição.");JSONObject m=old==null?store.add("materials"):old;put(m,"name",val(name));put(m,"specification",val(spec));persist();materials();});}
 void projectMaterials(JSONObject p){screen("projectMaterials","Materiais do projeto");JSONArray linked=p.optJSONArray("materialLocalIds");if(linked==null){linked=new JSONArray();put(p,"materialLocalIds",linked);}final JSONArray links=linked;note("Selecione materiais reais do catálogo local. Nenhuma movimentação de estoque será criada.");if(store.list("materials").length()==0)note("Cadastre materiais na tela inicial antes de selecionar.");for(int i=0;i<store.list("materials").length();i++){JSONObject m=store.list("materials").optJSONObject(i);CheckBox c=new CheckBox(this);c.setTextColor(TEXT);c.setText(m.optString("name"));String id=m.optString("id");for(int j=0;j<links.length();j++)if(id.equals(links.optString(j)))c.setChecked(true);root.addView(c);c.setOnCheckedChangeListener((b,checked)->{JSONArray updated=new JSONArray();for(int j=0;j<links.length();j++)if(!id.equals(links.optString(j)))updated.put(links.optString(j));if(checked)updated.put(id);while(links.length()>0)links.remove(0);for(int j=0;j<updated.length();j++)links.put(updated.optString(j));persist();});}button("VOLTAR AO PROJETO",()->go(()->editProject(p)));}
 JSONObject budgetData(JSONObject p){JSONObject b=p.optJSONObject("budget");if(b==null){b=new JSONObject();put(p,"budget",b);}return b;}
 BigDecimal total(JSONObject p)throws Exception{JSONObject b=budgetData(p);return Commercial.total(Commercial.area(measure(p,"Largura").toPlainString(),measure(p,"Altura").toPlainString()),Integer.parseInt(b.optString("quantity","1")),Commercial.amount(b.optString("price","0")),Commercial.amount(b.optString("service","0")),Commercial.amount(b.optString("discount","0")),Commercial.amount(b.optString("extra","0")));}
 void budget(JSONObject p)throws Exception{validateProject(p);screen("budget","Orçamento comercial");note(p.optString("title")+" • preços informados pelo profissional");JSONObject b=budgetData(p);EditText quantity=number("Quantidade",b.optString("quantity","1")),price=number("Valor por m² — R$ (ex.: 100,50)",b.optString("price","0")),service=number("Serviço adicional — R$",b.optString("service","0")),discount=number("Desconto em dinheiro — R$",b.optString("discount","0")),extra=number("Acréscimo em dinheiro — R$",b.optString("extra","0"));TextView result=text("Informe os valores e toque em CALCULAR.",20,TEXT);saveScreen=()->{put(b,"quantity",val(quantity));put(b,"price",val(price));put(b,"service",val(service));put(b,"discount",val(discount));put(b,"extra",val(extra));};button("CALCULAR / SALVAR ORÇAMENTO",()->{flush();BigDecimal sum=total(p);put(b,"calculated",true);persist();result.setText(budgetSummary(p));message("TOTAL: "+Commercial.money(sum)+"\nOrçamento não registra recebimento.");});if(b.optBoolean("calculated"))try{result.setText(budgetSummary(p));}catch(Exception ignored){}button("PRÉVIA / PDF / IMPRIMIR",()->{flush();requireClient(p);total(p);document("Orçamento comercial",budgetDocument(p));});button("VOLTAR AO PROJETO",()->go(()->editProject(p)));note("Sem percentuais nesta etapa. Área, quantidade e dinheiro são campos distintos. Nenhum pagamento, venda ou estoque é alterado.");}
 String budgetSummary(JSONObject p)throws Exception{JSONObject b=budgetData(p);BigDecimal area=Commercial.area(measure(p,"Largura").toPlainString(),measure(p,"Altura").toPlainString());int q=Integer.parseInt(b.optString("quantity","1"));BigDecimal price=Commercial.amount(b.optString("price","0"));return "Área unitária: "+decimal(area)+" m²\nQuantidade: "+q+"\nValor por m²: "+Commercial.money(price)+"\nValor base: "+Commercial.money(area.multiply(BigDecimal.valueOf(q)).multiply(price))+"\nServiço adicional: "+Commercial.money(Commercial.amount(b.optString("service","0")))+"\nDesconto: "+Commercial.money(Commercial.amount(b.optString("discount","0")))+"\nAcréscimo: "+Commercial.money(Commercial.amount(b.optString("extra","0")))+"\nTOTAL FINAL: "+Commercial.money(total(p));}
 String decimal(BigDecimal n){return n.setScale(2,RoundingMode.HALF_UP).toPlainString().replace('.',',');}
 JSONObject requireClient(JSONObject p)throws Exception{JSONObject c=store.find("clients",p.optString("clientLocalId"));if(c==null)throw new Exception("Selecione um cliente no projeto.");return c;}
 String projectInfo(JSONObject p)throws Exception{JSONObject c=requireClient(p);StringBuilder s=new StringBuilder("ANGRA VIDROS\n\nProjeto: "+p.optString("title")+"\nID: "+p.optString("id")+"\nCliente: "+c.optString("name")+"\nDocumento: "+c.optString("document")+"\nTelefone: "+c.optString("phone")+"\nEndereço: "+c.optString("address")+"\nServiço: "+p.optString("type")+"\nModelo: "+p.optString("model")+"\n\n");JSONArray a=p.getJSONArray("measures");for(int i=0;i<a.length();i++){JSONObject m=a.getJSONObject(i);s.append(m.optString("label")).append(": ").append(m.optString("value")).append(' ').append(m.optString("unit")).append('\n');}return s.toString();}
 String budgetDocument(JSONObject p)throws Exception{return projectInfo(p)+"\n"+budgetSummary(p)+"\n\nObservações: "+p.optString("configuration")+"\n\nORÇAMENTO COMERCIAL — não é recibo nem ordem de fabricação. Valores informados pelo profissional. Cadastro empresarial completo será obtido na integração com o PDV.";}
 void contract(JSONObject p)throws Exception{validateProject(p);requireClient(p);screen("contract","Contrato do projeto");note("Texto editável, sem cláusulas jurídicas presumidas. Salvar cria uma revisão; revisões anteriores permanecem disponíveis.");JSONObject contract=p.optJSONObject("contract");if(contract==null){contract=new JSONObject();put(p,"contract",contract);}final JSONObject c=contract;EditText clauses=input("Objeto, condições, prazo, instalação, responsabilidades e observações",c.optString("text"),true);clauses.setMinLines(8);text("Projeto e cliente são carregados do vínculo existente.",14,MUTED);button("SALVAR NOVA REVISÃO",()->{if(val(clauses).isEmpty())throw new Exception("Revise e informe o texto do contrato.");String content=projectInfo(p)+"\nValor comercial: "+Commercial.money(total(p))+"\n\n"+val(clauses);JSONArray versions=c.optJSONArray("revisions");if(versions==null){versions=new JSONArray();put(c,"revisions",versions);}JSONObject last=versions.optJSONObject(versions.length()-1);if(last==null||!content.equals(last.optString("content"))){JSONObject v=new JSONObject();put(v,"number",versions.length()+1);put(v,"savedAt",System.currentTimeMillis());put(v,"content",content);versions.put(v);}put(c,"text",val(clauses));persist();message("Contrato salvo. Nenhum pagamento ou venda foi criado.");});button("REVISÕES SALVAS / PDF",()->{JSONArray versions=c.optJSONArray("revisions");if(versions==null||versions.length()==0)throw new Exception("Salve uma revisão primeiro.");String[] names=new String[versions.length()];for(int i=0;i<names.length;i++){JSONObject v=versions.getJSONObject(i);names[i]="Revisão "+v.optInt("number")+" • "+new java.text.SimpleDateFormat("dd/MM/yyyy HH:mm",new Locale("pt","BR")).format(new Date(v.optLong("savedAt")));}new InteriorVisuals.Dialog(this).setTitle("Contratos preservados").setItems(names,(d,n)->run(()->document("Contrato • "+names[n],versions.getJSONObject(n).getString("content")))).show();});button("VOLTAR AO PROJETO",()->go(()->editProject(p)));}
 void tempera(JSONObject p){screen("tempera","Projeto para têmpera");note("Registro das especificações do profissional. Não calcula tolerâncias, furação, tratamentos ou regras do fabricante.");EditText spec=input("Especificações técnicas fornecidas pelo profissional",p.optString("temperaSpecification"),true);spec.setMinLines(6);saveScreen=()->put(p,"temperaSpecification",val(spec));button("SALVAR ESPECIFICAÇÕES",()->{flush();message("Especificações salvas.");});button("PRÉVIA / PDF",()->{flush();validateProject(p);if(val(spec).isEmpty())throw new Exception("Informe as especificações.");document("Especificações para têmpera",projectInfo(p)+"\nESPECIFICAÇÕES INFORMADAS\n"+val(spec)+"\n\nConferência técnica e autorização de fabricação são responsabilidade do profissional e do fornecedor.");});}
 void calculator(){screen("calculator","Calculadora de medidas");note("Área retangular e perímetro geométrico; sem fórmulas de fabricação.");EditText w=number("Largura",""),h=number("Altura","");text("Unidade das duas entradas desta calculadora",14,MUTED);Spinner unit=new Spinner(this);unit.setAdapter(new ArrayAdapter<>(this,R.layout.glass_selector_item,new String[]{"mm","cm","m"}));root.addView(unit);final String[] previous={"mm"};unit.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){String next=unit.getSelectedItem().toString();if(next.equals(previous[0]))return;try{String a=val(w).isEmpty()?"":Measures.convert(val(w),previous[0],next),b=val(h).isEmpty()?"":Measures.convert(val(h),previous[0],next);w.setText(a);h.setText(b);previous[0]=next;}catch(Exception e){unit.setSelection(Arrays.asList("mm","cm","m").indexOf(previous[0]));message(e.getMessage());}}});TextView result=text("",22,TEXT);button("CALCULAR",()->{String u=unit.getSelectedItem().toString();BigDecimal a=new BigDecimal(Measures.mm(val(w),u)),b=new BigDecimal(Measures.mm(val(h),u));result.setText("Área: "+decimal(Commercial.area(a.toPlainString(),b.toPlainString()))+" m²\nPerímetro: "+decimal(a.add(b).multiply(new BigDecimal("2")).divide(new BigDecimal("1000")))+" m");});}
 void pending(String module){screen("pending",module);if(module.equals("Estoque")&&sync!=null&&!sync.state.optString("tenant").isEmpty()){note("Consulta do estoque do PDV. Pode estar desatualizada quando offline. "+sync.status());JSONArray catalog=store.list("materials");for(int i=0;i<catalog.length();i++){JSONObject item=catalog.optJSONObject(i);if(!item.isNull("pdvId"))text(item.optString("name")+"\nCódigo: "+item.optString("barcode")+" • Estoque: "+item.optString("stock"),16,TEXT);}button("INTEGRAÇÃO COM PDV",()->go(this::integration));return;}text("PREPARADO PARA ETAPA POSTERIOR",17,CYAN);if(module.equals("Financeiro"))note("O Fluxo de Caixa oficial permanece no PDV. Este aplicativo não cria recebimentos, pagamentos nem movimentos paralelos. Orçamento e contrato não significam pagamento.");else if(module.equals("Estoque"))note("O estoque oficial permanece no PDV. Nenhuma quantidade fictícia, reserva ou baixa automática é realizada neste aplicativo.");else note("As regras de GlassCutPacking do PDV foram auditadas. A adaptação e validação de equivalência no Android ainda estão pendentes. Nenhum algoritmo alternativo de encaixe foi criado.");button("INTEGRAÇÃO PREPARADA",()->go(this::integration));}
 void integration(){screen("integration","Integração com o PDV");TextView state=text(sync==null?"Conexão iniciando…":sync.status(),17,TEXT);syncRefresh=()->state.setText(sync.status());note("Após conectar uma vez, as alterações válidas são sincronizadas automaticamente enquanto o app está aberto e ao retornar. Sem conexão, ficam pendentes neste aparelho.");if(sync!=null&&sync.state.optString("tenant").isEmpty()){EditText code=input("Código de conexão mostrado no PDV","",false);button("CONECTAR AO PDV",()->sync.connect(val(code)));}button("REVISAR CONFLITOS / PENDÊNCIAS",()->{if(sync!=null)sync.conflicts();});if(current!=null){button("EXPORTAR PROJETO EM JSON",()->exportProject(current));button("ABRIR PROJETO ATUAL",()->editProject(current));}note("Exportação manual é contingência. Orçamento/projeto não gera venda, pagamento ou baixa de estoque. Produtos e estoque vêm do PDV.");}
 JSONObject exportData(JSONObject p)throws Exception{validateProject(p);JSONObject payload=new JSONObject();payload.put("schemaVersion",2).put("kind","angra.professional.project").put("exportedAt",System.currentTimeMillis()).put("source","ANGRA VIDROS").put("syncState","PENDING_PDV_IMPORT").put("project",new JSONObject(p.toString()));JSONObject client=store.find("clients",p.optString("clientLocalId"));payload.put("client",client==null?JSONObject.NULL:new JSONObject(client.toString()));JSONArray materials=new JSONArray(),links=p.optJSONArray("materialLocalIds");if(links!=null)for(int i=0;i<links.length();i++){JSONObject m=store.find("materials",links.optString(i));if(m!=null)materials.put(new JSONObject(m.toString()));}payload.put("materials",materials);return payload;}
 void exportProject(JSONObject p)throws Exception{File f=new File(exportDir(),"projeto-"+p.optString("id")+".json");Files.write(f.toPath(),exportData(p).toString(2).getBytes(StandardCharsets.UTF_8));share(f,"application/json");}
 File exportDir(){File d=new File(getFilesDir(),"exports");d.mkdirs();return d;}
 void share(File f,String mime){Uri uri=FileProvider.getUriForFile(this,getPackageName()+".files",f);Intent i=new Intent(Intent.ACTION_SEND).setType(mime).putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri("documento",uri));startActivity(Intent.createChooser(i,"Compartilhar documento"));}
 void document(String heading,String content){ScrollView container=new ScrollView(this);TextView text=new TextView(this);text.setPadding(px(20),px(16),px(20),px(16));text.setText(heading+"\n\n"+content);text.setTextIsSelectable(true);text.setTextSize(16);container.addView(text);new InteriorVisuals.Dialog(this).setTitle("Prévia do documento").setView(container).setPositiveButton("GERAR PDF",(d,w)->run(()->share(makePdf(heading,content),"application/pdf"))).setNeutralButton("IMPRIMIR",(d,w)->run(()->print(makePdf(heading,content)))).setNegativeButton("FECHAR",null).show();}
 File makePdf(String heading,String content)throws Exception{File file=new File(exportDir(),"documento-"+System.currentTimeMillis()+".pdf");PdfDocument pdf=new PdfDocument();Paint paint=new Paint(3);paint.setTextSize(11);paint.setColor(Color.BLACK);ArrayList<String> lines=new ArrayList<>();for(String raw:(heading+"\n\n"+content).split("\n",-1)){if(raw.isEmpty()){lines.add("");continue;}String remaining=raw;while(!remaining.isEmpty()){int count=paint.breakText(remaining,true,499,null);if(count==0)throw new Exception("Texto inválido para PDF.");int at=count;if(count<remaining.length()){int space=remaining.lastIndexOf(' ',count);if(space>0)at=space;}lines.add(remaining.substring(0,at));remaining=remaining.substring(at).trim();}}for(int start=0,pageNo=1;start<lines.size();start+=44,pageNo++){PdfDocument.Page page=pdf.startPage(new PdfDocument.PageInfo.Builder(595,842,pageNo).create());Canvas canvas=page.getCanvas();int y=55;for(int i=start;i<Math.min(start+44,lines.size());i++){canvas.drawText(lines.get(i),48,y,paint);y+=16;}canvas.drawText("ANGRA VIDROS • Página "+pageNo,48,810,paint);pdf.finishPage(page);}try(FileOutputStream out=new FileOutputStream(file)){pdf.writeTo(out);}finally{pdf.close();}return file;}
 void print(File file){PrintManager manager=(PrintManager)getSystemService(PRINT_SERVICE);manager.print("ANGRA VIDROS",new PrintDocumentAdapter(){public void onLayout(PrintAttributes old,PrintAttributes next,CancellationSignal cancel,LayoutResultCallback callback,Bundle extras){if(cancel.isCanceled()){callback.onLayoutCancelled();return;}callback.onLayoutFinished(new PrintDocumentInfo.Builder(file.getName()).setContentType(PrintDocumentInfo.CONTENT_TYPE_DOCUMENT).setPageCount(PrintDocumentInfo.PAGE_COUNT_UNKNOWN).build(),true);}public void onWrite(PageRange[] pages,ParcelFileDescriptor dest,CancellationSignal cancel,WriteResultCallback callback){try(InputStream in=new FileInputStream(file);OutputStream out=new FileOutputStream(dest.getFileDescriptor())){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(cancel.isCanceled()){callback.onWriteCancelled();return;}out.write(buf,0,n);}callback.onWriteFinished(new PageRange[]{PageRange.ALL_PAGES});}catch(Exception e){callback.onWriteFailed("Não foi possível imprimir.");}}},new PrintAttributes.Builder().setMediaSize(PrintAttributes.MediaSize.ISO_A4).build());}
 File photoDir(){return PhotoAttachment.directory(this,current);}
 void photoPreview(JSONObject p){File file=new File(PhotoAttachment.directory(this,p),"photo.jpg");text("Foto do local",18,TEXT);if(file.exists()){ImageView preview=new ImageView(this);preview.setImageURI(Uri.fromFile(file));preview.setScaleType(ImageView.ScaleType.CENTER_INSIDE);preview.setContentDescription("Foto vinculada ao projeto "+p.optString("title"));preview.setBackground(shape(SURFACE,12));root.addView(preview,new LinearLayout.LayoutParams(-1,px(185)));preview.setOnClickListener(v->enlargePhoto(p));note("Foto salva neste projeto • toque para ampliar");}else note("Nenhuma foto vinculada. Adicione uma referência do local.");button(file.exists()?"VER / SUBSTITUIR FOTO":"ADICIONAR FOTO DO LOCAL",()->{flush();photoPage(p);});}
 void enlargePhoto(JSONObject p){ImageView full=new ImageView(this);full.setImageURI(Uri.fromFile(new File(PhotoAttachment.directory(this,p),"photo.jpg")));full.setAdjustViewBounds(true);full.setScaleType(ImageView.ScaleType.FIT_CENTER);new InteriorVisuals.Dialog(this).setTitle("Foto • "+p.optString("title")).setView(full).setPositiveButton("FECHAR",null).show();}
 void photoPage(JSONObject p){setCurrent(p);screen("photo","Foto do local / projeto");note("Documento visual vinculado ao projeto. Sem IA ou transmissão automática.");File f=new File(photoDir(),"photo.jpg");if(f.exists()){ImageView image=new ImageView(this);image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setImageURI(Uri.fromFile(f));image.setContentDescription("Foto vinculada ao projeto");root.addView(image,new LinearLayout.LayoutParams(-1,px(300)));image.setOnClickListener(v->enlargePhoto(p));button("SUBSTITUIR FOTO",()->new InteriorVisuals.Dialog(this).setMessage("Substituir a foto deste projeto?").setPositiveButton("CÂMERA",(d,n)->run(this::camera)).setNeutralButton("IMPORTAR",(d,n)->run(this::importPhoto)).setNegativeButton("VOLTAR",null).show());button("REMOVER FOTO",()->new InteriorVisuals.Dialog(this).setMessage("Remover a foto vinculada a este projeto?").setPositiveButton("REMOVER",(d,n)->run(()->{PhotoAttachment.remove(this,p);persist();photoPage(p);})).setNegativeButton("VOLTAR",null).show());}else{button("TIRAR FOTO DO LOCAL",this::camera);button("IMPORTAR FOTO",this::importPhoto);}button("VOLTAR AO PROJETO",()->editProject(p));}
 void pendingPhoto(){getPreferences(0).edit().putString("photoTargetProject",current.optString("id")).commit();}
 void importPhoto(){pendingPhoto();startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE),2);}
 void camera(){File f=new File(photoDir(),"capture.jpg");Uri u=FileProvider.getUriForFile(this,getPackageName()+".files",f);Intent i=new Intent(MediaStore.ACTION_IMAGE_CAPTURE).putExtra(MediaStore.EXTRA_OUTPUT,u).addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri("foto",u));if(i.resolveActivity(getPackageManager())==null){message("Câmera indisponível. Use importar foto.");return;}pendingPhoto();startActivityForResult(i,1);}
 @Override protected void onActivityResult(int req,int code,Intent data){super.onActivityResult(req,code,data);if(req!=1&&req!=2)return;String targetId=getPreferences(0).getString("photoTargetProject",current==null?"":current.optString("id"));getPreferences(0).edit().remove("photoTargetProject").apply();if(code!=RESULT_OK)return;run(()->{JSONObject target=store.find("projects",targetId);if(target==null)throw new IOException("Projeto da foto não encontrado. Nenhuma outra foto foi alterada.");File targetDir=PhotoAttachment.directory(this,target);Uri u=req==1?Uri.fromFile(new File(targetDir,"capture.jpg")):data.getData();BitmapFactory.Options opts=new BitmapFactory.Options();opts.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(u)){BitmapFactory.decodeStream(in,null,opts);}opts.inSampleSize=Math.max(1,Math.max(opts.outWidth,opts.outHeight)/1600);opts.inJustDecodeBounds=false;Bitmap b;try(InputStream in=getContentResolver().openInputStream(u)){b=BitmapFactory.decodeStream(in,null,opts);}if(b==null)throw new IOException("Não foi possível ler a foto.");int orient;try(InputStream in=getContentResolver().openInputStream(u)){orient=new ExifInterface(in).getAttributeInt(ExifInterface.TAG_ORIENTATION,1);}Matrix m=new Matrix();if(orient==6)m.postRotate(90);if(orient==3)m.postRotate(180);if(orient==8)m.postRotate(270);Bitmap normalized=Bitmap.createBitmap(b,0,0,b.getWidth(),b.getHeight(),m,true);ByteArrayOutputStream encoded=new ByteArrayOutputStream();normalized.compress(Bitmap.CompressFormat.JPEG,90,encoded);PhotoAttachment.save(this,target,encoded.toByteArray());persist();if(req==1)new File(targetDir,"capture.jpg").delete();setCurrent(target);editProject(target);for(int i=0;i<root.getChildCount();i++){View child=root.getChildAt(i);if(child instanceof ImageView){scroll.post(()->scroll.smoothScrollTo(0,Math.max(0,child.getTop()-px(35))));break;}}});}
 @Override protected void onResume(){super.onResume();if(sync!=null)sync.tick();}
 @Override protected void onDestroy(){if(sync!=null)sync.close();super.onDestroy();}
 @Override public void onBackPressed(){if(page.equals("home")){super.onBackPressed();return;}go(this::home);}
 @Override protected void onPause(){if(store!=null)run(()->flush());super.onPause();}
 final class CutField {final EditText value;final Spinner unit;String previous;CutField(String caption,String raw,String u){value=number(caption,raw);unit=new Spinner(MainActivity.this);unit.setAdapter(new ArrayAdapter<>(MainActivity.this,R.layout.glass_selector_item,new String[]{"mm","cm","m"}));previous=Arrays.asList("mm","cm","m").contains(u)?u:"mm";unit.setSelection(Arrays.asList("mm","cm","m").indexOf(previous));root.addView(unit);unit.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){String next=unit.getSelectedItem().toString();if(next.equals(previous))return;try{if(!val(value).isEmpty())value.setText(Measures.convert(val(value),previous,next));previous=next;}catch(Exception e){unit.setSelection(Arrays.asList("mm","cm","m").indexOf(previous));message(e.getMessage());}}});}String mm(){return Measures.mm(val(value),unit.getSelectedItem().toString());}}
 JSONObject cutData(JSONObject p){JSONObject c=p.optJSONObject("cut");if(c==null){c=new JSONObject();put(c,"pieces",new JSONArray());put(p,"cut",c);}return c;}
 void cut(JSONObject p){screen("cut","Plano de corte");note(CutPacking.DISCLAIMER);JSONObject c=cutData(p);CutField width=new CutField("Largura da chapa",c.optString("width"),c.optString("widthUnit","mm")),height=new CutField("Altura da chapa",c.optString("height"),c.optString("heightUnit","mm"));CheckBox rotate=new CheckBox(this);rotate.setText("Permitir rotação 90° (também depende de cada peça)");rotate.setTextColor(TEXT);rotate.setChecked(c.optBoolean("allowRotation",true));root.addView(rotate);saveScreen=()->{put(c,"width",val(width.value));put(c,"widthUnit",width.unit.getSelectedItem().toString());put(c,"height",val(height.value));put(c,"heightUnit",height.unit.getSelectedItem().toString());put(c,"allowRotation",rotate.isChecked());};button("+ ADICIONAR PEÇA",()->go(()->cutPiece(p,null)));JSONArray pieces=c.optJSONArray("pieces");for(int i=0;pieces!=null&&i<pieces.length();i++){JSONObject piece=pieces.optJSONObject(i);button(piece.optString("description","Peça")+" • "+piece.optString("width")+" "+piece.optString("widthUnit")+" × "+piece.optString("height")+" "+piece.optString("heightUnit")+" • qtd "+piece.optInt("quantity"),()->go(()->cutPiece(p,piece)));}button("RECALCULAR PLANO",()->{flush();cutResult(p);});button("SALVAR PLANO",()->{flush();message("Chapa e peças salvas no projeto.");});button("VOLTAR AO PROJETO",()->go(()->editProject(p)));}
 void cutPiece(JSONObject p,JSONObject old){screen("cutPiece",old==null?"Adicionar peça":"Editar peça");note("Dimensões de corte fornecidas pelo profissional. Não são copiadas automaticamente do vão.");EditText description=input("Identificação / descrição da peça",old==null?"":old.optString("description"),false);CutField w=new CutField("Largura da peça",old==null?"":old.optString("width"),old==null?"mm":old.optString("widthUnit","mm")),h=new CutField("Altura da peça",old==null?"":old.optString("height"),old==null?"mm":old.optString("heightUnit","mm"));EditText q=number("Quantidade de peças",old==null?"1":String.valueOf(old.optInt("quantity",1))),material=input("Material informado (peças de materiais distintos não compartilham chapa)",old==null?"":old.optString("material"),false);CheckBox rotation=new CheckBox(this);rotation.setTextColor(TEXT);rotation.setText("Permitir rotação desta peça");rotation.setChecked(old==null||old.optBoolean("allowRotation",true));root.addView(rotation);button("SALVAR PEÇA",()->{if(val(description).isEmpty())throw new Exception("Informe a identificação da peça.");CutPacking.valid(new BigDecimal(w.mm()));CutPacking.valid(new BigDecimal(h.mm()));int quantity=Integer.parseInt(val(q));if(quantity<1||quantity>1000)throw new Exception("Quantidade: 1 a 1000.");JSONObject piece=old==null?new JSONObject().put("id",UUID.randomUUID().toString()):old;put(piece,"description",val(description));put(piece,"width",val(w.value));put(piece,"widthUnit",w.unit.getSelectedItem().toString());put(piece,"height",val(h.value));put(piece,"heightUnit",h.unit.getSelectedItem().toString());put(piece,"quantity",quantity);put(piece,"material",val(material));put(piece,"allowRotation",rotation.isChecked());if(old==null)cutData(p).getJSONArray("pieces").put(piece);persist();cut(p);});if(old!=null)button("EXCLUIR PEÇA",()->new InteriorVisuals.Dialog(this).setMessage("Excluir somente esta peça do plano?").setPositiveButton("EXCLUIR",(d,n)->run(()->{JSONArray pieces=cutData(p).getJSONArray("pieces");for(int i=0;i<pieces.length();i++)if(pieces.getJSONObject(i).optString("id").equals(old.optString("id"))){pieces.remove(i);break;}persist();cut(p);})).setNegativeButton("VOLTAR",null).show());}
 CutPacking.Result calculateCut(JSONObject p)throws Exception{JSONObject c=cutData(p);ArrayList<CutPacking.Piece> pieces=new ArrayList<>();JSONArray a=c.getJSONArray("pieces");for(int i=0;i<a.length();i++){JSONObject x=a.getJSONObject(i);pieces.add(new CutPacking.Piece(x.getString("id"),x.getString("description"),Measures.mm(x.getString("width"),x.getString("widthUnit")),Measures.mm(x.getString("height"),x.getString("heightUnit")),x.getInt("quantity"),x.optString("material"),x.optBoolean("allowRotation",true)));}return CutPacking.calculate(Measures.mm(c.optString("width"),c.optString("widthUnit")),Measures.mm(c.optString("height"),c.optString("heightUnit")),pieces,c.optBoolean("allowRotation",true));}
 String cutSummary(CutPacking.Result r){return "Chapas: "+r.sheets.size()+"\nÁrea utilizada: "+decimal(r.used())+" m²\nÁrea não utilizada: "+decimal(r.unused())+" m²\nAproveitamento: "+decimal(r.utilization())+"%\nDesperdício: "+decimal(r.total().signum()==0?BigDecimal.ZERO:new BigDecimal("100").subtract(r.utilization()))+"%\nNão acomodadas: "+r.rejectedQuantity();}
 void cutResult(JSONObject p)throws Exception{CutPacking.Result result=calculateCut(p);screen("cutResult","Resultado geométrico");text(cutSummary(result),19,TEXT);note(CutPacking.DISCLAIMER);StringBuilder report=new StringBuilder("ANGRA VIDROS\nProjeto: "+p.optString("title")+"\nChapa: "+result.w.toPlainString()+" × "+result.h.toPlainString()+" mm\n"+cutSummary(result)+"\n\n");int n=0;for(CutPacking.Sheet sheet:result.sheets){text("Chapa "+(++n)+" • "+sheet.material,17,TEXT);View drawing=new View(this){final Paint paint=new Paint(3);@Override protected void onDraw(Canvas canvas){super.onDraw(canvas);canvas.drawColor(SURFACE);float scale=Math.min((getWidth()-30)/result.w.floatValue(),(getHeight()-30)/result.h.floatValue());paint.setStyle(Paint.Style.STROKE);paint.setColor(MUTED);canvas.drawRect(15,15,15+result.w.floatValue()*scale,15+result.h.floatValue()*scale,paint);for(CutPacking.Placement place:sheet.placed){paint.setStyle(Paint.Style.FILL);paint.setColor(0xff176b83);float x=15+place.x.floatValue()*scale,y=15+place.y.floatValue()*scale;canvas.drawRect(x,y,x+place.w.floatValue()*scale,y+place.h.floatValue()*scale,paint);paint.setStyle(Paint.Style.STROKE);paint.setColor(CYAN);canvas.drawRect(x,y,x+place.w.floatValue()*scale,y+place.h.floatValue()*scale,paint);}}};root.addView(drawing,new LinearLayout.LayoutParams(-1,px(230)));for(CutPacking.Placement place:sheet.placed){String line=place.piece.description+" #"+place.instance+" — "+place.w.toPlainString()+" × "+place.h.toPlainString()+" mm; X="+place.x.toPlainString()+", Y="+place.y.toPlainString()+(place.rotated?"; rotação 90°":"");note(line);report.append("Chapa ").append(n).append(": ").append(line).append('\n');}}for(CutPacking.Piece reject:result.rejected){String line="NÃO ACOMODADA: "+reject.description+" • qtd "+reject.quantity;note(line);report.append(line).append('\n');}report.append('\n').append(CutPacking.DISCLAIMER);button("PRÉVIA A4 / PDF / IMPRIMIR PLANO",()->document("Plano de corte geométrico",report.toString()));button("VOLTAR ÀS PEÇAS",()->cut(p));}

